sys_script_include.script:
var SendUpcomingEventReminder = Class.create();
SendUpcomingEventReminder.prototype = {
    initialize: function() {
    },

 sendReminders: function() {
        var today = new GlideDateTime();
        var upcomingDate = new GlideDateTime();
        upcomingDate.addDays(1); // Sends reminders for events happening tomorrow

        var attendeeGR = new GlideRecord('x_1790229_event_ma_attendee'); // Your attendee table
        attendeeGR.addNotNullQuery('u_event_id');
        attendeeGR.addQuery('u_event.u_event_date', '>=', today);
        attendeeGR.addQuery('u_event.u_event_date', '<', upcomingDate);
        attendeeGR.query();

        while (attendeeGR.next()) {
            var user = attendeeGR.u_attendee; // Reference to sys_user
            var event = attendeeGR.u_event_id;

            if (user) {
                // Send event to notification system
                gs.eventQueue('x_1790229_event_ma.upcoming_event_attendee_reminder', user, event.getDisplayValue('u_event_name'), event.getDisplayValue('u_event_date'));
            }
        }
    },

    type: 'SendUpcomingEventReminder'
};
